        return None
    if self.analytic_projection is None:
        return dict(original_cell=copy.deepcopy(cell), original_split=split,
            terminal_analytic_projection_paid=False,
            reasons=["actual_R580_binding_unpaid"],
            actual_binding_error_in_necessary_scope=True)
    try:
        return self.analytic_projection.commit_original_retirement(
            cell, diagnostic, split=split)
    except (ResourceStop, MemoryError):
        raise
